    address: "456 Supply Avenue, Quezon City",
    province: "Metro Manila",
    contact_person: "Maria Santos",
    phone: "+63 2 2345 6789",
    email: "info@abcsupplies.com",
    bir_tin: "234-567-890-000",
    is_active: true,
    created_at: "2024-01-02T00:00:00Z",
    updated_at: "2024-01-02T00:00:00Z"
  },
  {
    id: 3,
    name: "Metro Manila Electronics",
    address: "789 Electronics Road, Pasig City",
    province: "Metro Manila",
    contact_person: "Pedro Martinez",
    phone: "+63 2 3456 7890",
    email: "sales@metroelectronics.com",
    bir_tin: "345-678-901-000",
    is_active: true,
    created_at: "2024-01-03T00:00:00Z",
    updated_at: "2024-01-03T00:00:00Z"
  }
];

const mockProducts: Product[] = [
  {
    id: 1,
    name: "Office Chairs - Ergonomic",
    description: "High-quality ergonomic office chairs with adjustable features",
    unit: "pieces",
    unit_price: 2500.00,
    category: "Office Furniture",
    is_active: true
  },
  {
    id: 2,
    name: "Laptop Stands",
    description: "Adjustable laptop stands for better ergonomics",
    unit: "pieces",
    unit_price: 800.00,
    category: "Office Equipment",
    is_active: true
  },
  {
    id: 3,
    name: "Wireless Keyboards",
    description: "Bluetooth wireless keyboards with backlit keys",
    unit: "pieces",
    unit_price: 1200.00,
    category: "Computer Accessories",
    is_active: true
  },
  {
    id: 4,
    name: "Desk Organizers",
    description: "Multi-compartment desk organizers for office supplies",
    unit: "pieces",
    unit_price: 350.00,
    category: "Office Supplies",
    is_active: true
  }
];

const mockOrders: PurchaseOrder[] = [
  {
    id: 1,
    po_number: "PO-20250101-001",
    supplier_id: 1,
    supplier: mockSuppliers[0],
    delivery_address: "123 Ayala Avenue, Makati City, Philippines",
    notes: "Urgent delivery required",
    status: "Draft",
    total_amount: 60000.00,
    date_created: "2025-01-01T10:30:00Z",
    date_updated: "2025-01-01T10:30:00Z",
    items: [
      {
        id: 1,
        product_id: 1,
        product: mockProducts[0],
        quantity: 20,
        unit_price: 2500.00,
        total_price: 50000.00
      },
      {
        id: 2,
        product_id: 2,
        product: mockProducts[1],
        quantity: 10,
        unit_price: 800.00,
        total_price: 8000.00
      }
    ]
  },
  {
    id: 2,
    po_number: "PO-20250101-002",
    supplier_id: 2,
    supplier: mockSuppliers[1],
    delivery_address: "456 Supply Avenue, Quezon City, Philippines",
    notes: "Standard delivery",
    status: "Pending",
    total_amount: 45000.00,
    date_created: "2025-01-02T14:15:00Z",
    date_updated: "2025-01-02T14:15:00Z",
    items: [
      {
        id: 3,
        product_id: 3,
        product: mockProducts[2],
        quantity: 30,
        unit_price: 1200.00,
        total_price: 36000.00
      },
      {
        id: 4,
        product_id: 4,
        product: mockProducts[3],
        quantity: 25,
        unit_price: 350.00,
        total_price: 8750.00
      }
    ]
  },
  {
    id: 3,
    po_number: "PO-20250101-003",
    supplier_id: 3,
    supplier: mockSuppliers[2],
    delivery_address: "789 Electronics Road, Pasig City, Philippines",
    notes: "Premium delivery service",
    status: "Approved",
    total_amount: 75000.00,
    date_created: "2025-01-03T09:45:00Z",
    date_updated: "2025-01-03T09:45:00Z",
    items: [
      {
        id: 5,
        product_id: 1,
        product: mockProducts[0],
        quantity: 25,
        unit_price: 2500.00,
        total_price: 62500.00
      },
      {
        id: 6,
        product_id: 2,
        product: mockProducts[1],
        quantity: 15,
        unit_price: 800.00,
        total_price: 12000.00
      }
    ]
  },
  {
    id: 4,
    po_number: "PO-20250101-004",
    supplier_id: 1,
    supplier: mockSuppliers[0],
    delivery_address: "123 Ayala Avenue, Makati City, Philippines",
    notes: "Completed order",
    status: "Completed",
    total_amount: 32000.00,
    date_created: "2025-01-04T16:20:00Z",
    date_updated: "2025-01-05T10:30:00Z",
    items: [
      {
        id: 7,
        product_id: 4,
        product: mockProducts[3],
        quantity: 80,
        unit_price: 350.00,
        total_price: 28000.00
      },
      {
        id: 8,
        product_id: 2,
        product: mockProducts[1],
        quantity: 5,
        unit_price: 800.00,
        total_price: 4000.00
      }
    ]
  }
];

interface EmployeeFormDataItem {
  unit: string;
  item_description: string;
  quantity: number;
  unit_cost: number;
  total_cost: number;
}

interface EmployeeFormData {
  entity_name: string;
  fund_cluster: string;
  office_section: string;
  responsibility_center_code: string;
  date: string;
  remark: string;
  items: EmployeeFormDataItem[];
}

const Orders: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [editingOrder, setEditingOrder] = useState<PurchaseOrder | null>(null);
  const [showToast, setShowToast] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');
  const [usingMockData, setUsingMockData] = useState(false);
  const [showItemsModal, setShowItemsModal] = useState(false);
  const [selectedRequestItems, setSelectedRequestItems] = useState<any[]>([]);

  // Form state
  const [formData, setFormData] = useState<CreateOrderData>({
    supplier_id: 0,
    delivery_address: '',
    notes: '',
    items: []
  });

  // Employee purchase request form state
  const [employeeFormData, setEmployeeFormData] = useState<EmployeeFormData>({
    entity_name: user?.full_name || user?.username || '',
    fund_cluster: '',
    office_section: user?.department || '',
    responsibility_center_code: '',
    date: new Date().toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }).replace(/\//g, '/'),
    remark: '',
    items: Array(4).fill(null).map(() => ({
      unit: '',
      item_description: '',
      quantity: 0,
      unit_cost: 0.0,
      total_cost: 0.0
    }))
  });

  // Form validation
  const [errors, setErrors] = useState<{
    supplier_id?: string;
    delivery_address?: string;
    notes?: string;
    items?: string;
  }>({});

  // Convert purchase requests (from backend) into the purchase order shape
  const mapPurchaseRequestsToOrders = (purchaseRequests: PurchaseRequest[]): PurchaseOrder[] => {
    return purchaseRequests.map((pr: PurchaseRequest) => ({
      id: parseInt(pr.id) || hashString(pr.id),
      po_number: pr.pr_number,
      supplier_id: 0,
      supplier: {
        id: 0,
        name: pr.entity_name || pr.requested_by || 'N/A',
        address: '',
        province: '',
        contact_person: '',
        phone: '',
        bir_tin: '',
        is_active: true,
        created_at: pr.date_created,
        updated_at: pr.date_updated || pr.date_created
      },
      delivery_address: pr.office_section,
      notes: pr.remark || '',
      status:
        pr.status === 'Pending'
          ? 'Pending'
          : pr.status === 'Approved'
            ? 'Approved'
            : pr.status === 'Completed'
              ? 'Completed'
              : 'Draft',
      total_amount: pr.total_amount,
      date_created: pr.date_created,
      date_updated: pr.date_updated || pr.date_created,
      items: pr.items.map((item, index) => ({
        id: index + 1,
        product_id: index + 1,
        product: {
          id: index + 1,
          name: item.item_description,
          unit: item.unit,
          unit_price: item.unit_cost,
          category: '',
          is_active: true
        },
        quantity: item.quantity,
        unit_price: item.unit_cost,
        total_price: item.total_cost
      }))
    }));
  };

  // Helper function to hash string to number
  const hashString = (str: string): number => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32bit integer
    }
    return Math.abs(hash);
  };

  const handleSave = async () => {
    try {
      if (!currentOrder.po_number || !currentOrder.supplier) {
        setToastMessage('Please fill in all required fields');
        setToastType('warning');
        setShowToast(true);
        return;
      }

      setToastMessage('Order saved successfully');
      setToastType('success');
      setShowToast(true);
      setShowModal(false);

      setCurrentOrder({
        po_number: '',
        supplier: '',
        order_date: new Date().toISOString().split('T')[0],
        items: [],
        total_amount: 0,
        status: 'Draft',
        notes: ''
      });

      fetchOrders();
    } catch (err) {
      setToastMessage('Failed to save order');
      setToastType('error');
      setShowToast(true);
    }
  };

  const filteredOrders = orders.filter(order =>
    order.po_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
    order.supplier.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <LoadingSpinner size="lg" text="Loading Orders..." />;

  return (
    <Container fluid className="py-5">
      {error && (
        <Row className="mb-4">
          <Col>
            <div className="alert alert-danger alert-dismissible fade show" role="alert">
              <i className="bi bi-exclamation-circle me-2"></i>
              {error}
            </div>
          </Col>
        </Row>
      )}

      {/* Header Section */}
      <Row className="mb-5">
        <Col>
          <div className="d-flex justify-content-between align-items-center">
            <div>
              <h1 className="fw-bold text-dark mb-2">
                <i className="bi bi-cart text-primary me-3"></i>
                Purchase Orders
              </h1>
              <p className="text-muted fs-6">Manage and track purchase orders</p>
            </div>
            <Button
              variant="primary"
              size="lg"
              onClick={() => setShowModal(true)}
              className="px-4 py-2"
            >
              <i className="bi bi-plus-circle me-2"></i>
              New Order
            </Button>
          </div>
        </Col>
      </Row>

      {/* Search Section */}
      <Row className="mb-4">
        <Col md={6}>
          <InputGroup>
            <InputGroup.Text className="bg-light border-light">
              <i className="bi bi-search"></i>
            </InputGroup.Text>
            <Form.Control
              placeholder="Search by PO number or supplier..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="border-light"
            />
          </InputGroup>
        </Col>
      </Row>

      {/* Orders Table Section */}
      <Row>
        <Col>
          <Card className="border-0 shadow-sm rounded-lg overflow-hidden">
            <Card.Body className="p-0">
              <div style={{ overflowX: 'auto' }}>
                <Table hover className="mb-0 table-striped">
                  <thead className="bg-light border-bottom">
                    <tr>
                      <th className="fw-bold text-dark">PO Number</th>
                      <th className="fw-bold text-dark">Supplier</th>
                      <th className="fw-bold text-dark">Date</th>
                      <th className="fw-bold text-dark text-end">Total Amount</th>
                      <th className="fw-bold text-dark text-center">Status</th>
                      <th className="fw-bold text-dark text-center">Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredOrders.length === 0 ? (
                      <tr>
                        <td colSpan={6} className="text-center py-5 text-muted">
                          <i className="bi bi-inbox fs-1 d-block mb-2"></i>
                          <span>No orders found</span>
                        </td>
                      </tr>
                    ) : (
                      filteredOrders.map((order) => (
                        <tr key={order.id} className="align-middle">
                          <td className="fw-bold text-primary">{order.po_number}</td>
                          <td>{order.supplier}</td>
                          <td>
                            <small>{new Date(order.order_date).toLocaleDateString()}</small>
                          </td>
                          <td className="text-end">
                            <span className="fw-bold text-success">₱{order.total_amount.toFixed(2)}</span>
                          </td>
                          <td className="text-center">
                            <Badge bg={order.status === 'Completed' ? 'success' : order.status === 'Approved' ? 'info' : 'warning'} className="px-3 py-2">
                              {order.status}
                            </Badge>
                          </td>
                          <td className="text-center">
                            <Button
                              variant="outline-info"
                              size="sm"
                              className="rounded-circle"
                              style={{ width: '36px', height: '36px', padding: 0 }}
                            >
                              <i className="bi bi-eye"></i>
                            </Button>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </Table>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Create Order Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-light border-bottom">
          <Modal.Title className="fw-bold">
            <i className="bi bi-file-earmark-plus text-primary me-2"></i>
            New Purchase Order
          </Modal.Title>
        </Modal.Header>
        <Modal.Body className="p-4">
          <Form>
            <Row className="g-3 mb-4">
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="fw-bold small">PO Number *</Form.Label>
                  <Form.Control
                    value={currentOrder.po_number}
                    onChange={(e) => setCurrentOrder({ ...currentOrder, po_number: e.target.value })}
                    placeholder="e.g., PO-2026-001"
                    size="sm"
                    className="border-light"
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Supplier *</Form.Label>
                  <Form.Control
                    value={currentOrder.supplier}
                    onChange={(e) => setCurrentOrder({ ...currentOrder, supplier: e.target.value })}
                    placeholder="Supplier name"
                    size="sm"
                    className="border-light"
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row className="g-3 mb-4">
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Order Date *</Form.Label>
                  <Form.Control
                    type="date"
                    value={currentOrder.order_date}
                    onChange={(e) => setCurrentOrder({ ...currentOrder, order_date: e.target.value })}
                    size="sm"
                    className="border-light"
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Status</Form.Label>
                  <Form.Select
                    value={currentOrder.status}
                    onChange={(e) => setCurrentOrder({ ...currentOrder, status: e.target.value as any })}
                    size="sm"
                    className="border-light"
                  >
                    <option value="Draft">Draft</option>
                    <option value="Pending">Pending</option>
                    <option value="Approved">Approved</option>
                    <option value="Completed">Completed</option>
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-4">
              <Form.Label className="fw-bold small">Notes</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                value={currentOrder.notes}
                onChange={(e) => setCurrentOrder({ ...currentOrder, notes: e.target.value })}
                placeholder="Additional notes"
                size="sm"
                className="border-light"
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer className="bg-light border-top">
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel
          </Button>
          <Button variant="primary" onClick={handleSave} className="px-4">
            <i className="bi bi-check-circle me-2"></i>
            Save Order
          </Button>
        </Modal.Footer>
      </Modal>

      <Toast
        show={showToast}
        onClose={() => setShowToast(false)}
        message={toastMessage}
        type={toastType}
        delay={3000}
      />
    </Container>
  );
};

export default Orders;
